/** b9bca8b가 이 글을 잡았는지(그때처럼 공백만 지우고 검사) */
export function headMatch(text: string): Kind | null {
  const t = text.replace(/\s+/g, "");
  if (!t) return null;
  for (const [kind, patterns] of HEAD_RULES) if (patterns.some((p) => p.test(t))) return kind;
  return null;
}
